mapper.select:
SELECT ctc.code_type_code ,ctc.code_type_code_desc ,lc.common_code ,lcc.common_code_name FROM lgcom_common_code_c lc ,lgcom_common_code_multi_lang_c lcc ,lgcom_code_type_code_c ctc WHERE ctc.code_type_code = lc.code_type_code AND ctc.code_type_code = lcc.code_type_code AND lc.common_code = lcc.common_code AND lc.code_type_code = lcc.code_type_code AND lc.company_id = lcc.company_id AND lc.inventory_organization_id = lcc.inventory_organization_id AND ctc.use_flag = 'Y' AND lc.use_flag = 'Y' AND lcc.language_code = #{USER_SESSION.languageCode} AND NVL(lc.apply_start_date, SYSDATE) <= SYSDATE AND NVL(lc.apply_end_date, SYSDATE) >= SYSDATE AND UPPER(ctc.code_type_code) LIKE UPPER(#{codeTypeCode}) || '%'
AND ctc.system_code = #{systemCode}
AND ctc.module_code = #{moduleCode}
ORDER BY lc.sort_order_no
